input.old_string:
def __init__(self, data: int | list[int]) -> None:
    if isinstance(data, int):
        if data < 0:
            raise ValueError("size must be non-negative")
        self._n = data
        self._tree = [0] * (self._n + 1)
        self._arr = [0] * self._n
    else:
        self._n = len(data)
        self._tree = [0] * (self._n + 1)
        self._arr = list(data)
        for i in range(self._n):
            j = i + 1
            while j <= self._n:
                self._tree[j] += self._arr[i]
                j += j & -j

input.new_string:
def __init__(self, data: int | list[int]) -> None:
    # BIT fields
    if isinstance(data, int):
        if data < 0:
            raise ValueError("size must be non-negative")
        self._n = data
        self._tree = [0] * (self._n + 1)
        self._arr = [0] * self._n
    else:
        self._n = len(data)
        self._tree = [0] * (self._n + 1)
        self._arr = list(data)
        for i in range(self._n):
            j = i + 1
            while j <= self._n:
                self._tree[j] += self._arr[i]
                j += j & -j

    # Stack fields (O(1) push/pop/top/getMin/getMax)
    self._stack: deque[Any] = deque()
    self._min_stack: deque[Any] = deque()
    self._max_stack: deque[Any] = deque()

    # Hash-map fields (O(1) put/get/remove)
    self._map: dict[str, Any] = {}
    self._key_index: dict[str, int] = {}
